import { createFeatureFlags, createMemoryProvider } from "@zudojs/feature-flags";

const flags = createFeatureFlags({
  provider: createMemoryProvider([{
    key: "task-sorting",
    enabled: true,
    defaultValue: "by-date",
    rules: [{ type: "variant", variants: [{ key: "by-date", weight: 50 }, { key: "by-priority", weight: 50 }] }],
  }]),
});

async function groupSizes(count) {
  const groups = new Map();
  for (let i = 0; i < count; i++) {
    const result = await flags.evaluate("task-sorting", { userId: `user-${i}` });
    groups.set(result.value, (groups.get(result.value) ?? 0) + 1);
  }
  return groups;
}

const groups = await groupSizes(200);
console.log(groups.size, (groups.get("by-date") ?? 0) + (groups.get("by-priority") ?? 0) === 200);
